
import "server-only";
import { cookies } from "next/headers";

/**
 * Store a session token in an HTTP-only cookie.
 *
 * Must be called from a Server Action or Route Handler.
 *
 * @param sessionToken - Token generated by the authentication backend.
 */
export async function saveSession(sessionToken: string) {
  const cookieStore = await cookies();

  cookieStore.set("session", sessionToken, {
    httpOnly: true,
    secure: process.env.NODE_ENV === "production",
    sameSite: "lax",
    path: "/",
    maxAge: 60 * 60 * 24, // 24 hours
  });
}

/**
 * Retrieve the session token from the request cookies.
 *
 * @returns The session token or undefined if no cookie exists.
 */
export async function getSession() {
  const cookieStore = await cookies();

  return cookieStore.get("session")?.value;
}

/**
 * Delete the session cookie.
 *
 * Must be called from a Server Action or Route Handler.
 */
export async function deleteSession() {
  const cookieStore = await cookies();

  cookieStore.delete("session");
}
